trace = []
def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        return None, '除数不能为 0'
    except TypeError:
        return None, '请输入数字'
    else:
        return result, ''
    finally:
        trace.append('结算')

print(safe_divide(10, 2))
print(safe_divide(10, 0))
print(safe_divide('a', 2))
print(trace)
